
import type { WorkerFidelity } from '../agent-variants/contracts';

type WorkerAgentDefinition = {
  fidelity: WorkerFidelity;
  agentType: string;
  filename: string;
  content: string;
};

export type WorkerEffortLevel = 'low' | 'medium' | 'high';

export const FIDELITY_WORKER_TIERS: Record<
  WorkerFidelity,
  { model: string; effort: WorkerEffortLevel }
> = {
  low: { model: 'claude-opus-4-8', effort: 'low' },
  medium: { model: 'claude-opus-4-8', effort: 'medium' },
  high: { model: 'claude-opus-4-8', effort: 'high' },
};

export const DEFAULT_WORKER_FIDELITY: WorkerFidelity = 'high';

export const RIVET_WORKER_AGENT_TYPE = 'rivet-worker';

export const RIVET_WORKER_AGENT_TYPES: Record<WorkerFidelity, string> = {
  low: `${RIVET_WORKER_AGENT_TYPE}-low`,
  medium: `${RIVET_WORKER_AGENT_TYPE}-medium`,
  high: RIVET_WORKER_AGENT_TYPE,
};

export const RIVET_WORKER_DEFAULTS: {
  model: string;
  effort: WorkerEffortLevel;
} = FIDELITY_WORKER_TIERS[DEFAULT_WORKER_FIDELITY];

export const RIVET_WORKER_REFERENCE_CREATE_DEFAULTS: {
  model: string;
  effort: WorkerEffortLevel;
} = FIDELITY_WORKER_TIERS[DEFAULT_WORKER_FIDELITY];

export const RIVET_WORKER_AGENT_VERSION = 3;

const workerAgentContentFor = (fidelity: WorkerFidelity): string => {
  const agentType = RIVET_WORKER_AGENT_TYPES[fidelity];
  const defaults = FIDELITY_WORKER_TIERS[fidelity];
  return `---
name: ${agentType}
description: Implements one Rivet design variant from its server-authored briefing. Spawned by the Rivet variants flow — not intended for direct invocation.
model: ${defaults.model}
effort: ${defaults.effort}
---

[//]: # (rivet-worker-agent-version: ${RIVET_WORKER_AGENT_VERSION})

You implement exactly one Rivet design variant. Your prompt names a briefing
file: read it first and follow it exactly — its direction, mode contract,
workspace boundaries, and the completion command at the end are all
authoritative. Edit only your assigned workspace; never touch other
variants' workspaces; never run git commit or push. The moment your
workspace is done, run the briefing's completion command yourself, then
stop.
`;
};

export const RIVET_WORKER_AGENT_DEFINITIONS: Record<
  WorkerFidelity,
  WorkerAgentDefinition
> = Object.fromEntries(
  (['low', 'medium', 'high'] as const).map((fidelity) => {
    const agentType = RIVET_WORKER_AGENT_TYPES[fidelity];
    return [
      fidelity,
      {
        fidelity,
        agentType,
        filename: `${agentType}.md`,
        content: workerAgentContentFor(fidelity),
      },
    ];
  }),
) as Record<WorkerFidelity, WorkerAgentDefinition>;

export const RIVET_WORKER_AGENT_FILENAME =
  RIVET_WORKER_AGENT_DEFINITIONS[DEFAULT_WORKER_FIDELITY].filename;
